"definitions": [
  {
    "nodeType": "core.logic.loop",
    "supportsErrorHandling": true,
    "version": "2.4",
    "category": "control-flow",
    "description": "Iterate over a collection of items",
    "tags": [
      "control-flow",
      "loop",
      "iteration"
    ],
    "sortOrder": 20,
    "display": {
      "label": "Loop",
      "icon": "repeat",
      "shape": "container",
      "description": "Execute a sequence of actions repeatedly for each item in a collection"
    },
    "handleConfiguration": [
      {
        "position": "left",
        "boundary": "outer",
        "handles": [
          {
            "id": "input",
            "type": "target",
            "handleType": "input"
          }
        ]
      },
      {
        "position": "right",
        "boundary": "outer",
        "handles": [
          {
            "id": "success",
            "type": "source",
            "handleType": "output"
          },
          {
            "id": "error",
            "label": "Error",
            "type": "source",
            "handleType": "output",
            "visible": "{inputs.errorHandlingEnabled}",
            "constraints": {
              "maxConnections": 1
            }
          }
        ]
      },
      {
        "position": "left",
        "boundary": "inner",
        "handles": [
          {
            "id": "start",
            "label": "start",
            "type": "source",
            "handleType": "output"
          }
        ]
      },
      {
        "position": "right",
        "boundary": "inner",
        "handles": [
          {
            "id": "continue",
            "label": "continue",
            "type": "target",
            "handleType": "input"
          },
          {
            "id": "break",
            "label": "break",
            "type": "target",
            "handleType": "input",
            "visible": "inputs.breakEnabled"
          }
        ]
      }
    ],
    "model": {
      "type": "bpmn:SubProcess"
    },
    "inputDefinition": {
      "type": "object",
      "properties": {
        "collection": {
          "type": "array"
        },
        "parallel": {
          "type": "boolean"
        },
        "completionCondition": {
          "type": "string"
        },
        "breakEnabled": {
          "type": "boolean"
        }
      },
      "required": [
        "collection"
      ]
    },
    "inputDefaults": {
      "collection": [],
      "parallel": false,
      "completionCondition": "",
      "breakEnabled": false
    },
    "outputDefinition": {
      "currentItem": {
        "type": "any",
        "description": "The current item being iterated in the loop",
        "source": "=loopContext.currentItem",
        "var": "currentItem",
        "scope": "internal"
      },
      "currentIteration": {
        "type": "number",
        "description": "The current iteration number (1-based)",
        "source": "=loopContext.currentIteration",
        "var": "currentIteration",
        "scope": "internal"
      },
      "collection": {
        "type": "array",
        "description": "The collection being iterated over",
        "source": "=loopContext.collection",
        "var": "collection",
        "scope": "internal"
      },
      "output": {
        "type": "array",
        "description": "Aggregated results from all loop iterations",
        "source": "=loopContext.output",
        "var": "output",
        "scope": "external"
      },
      "error": {
        "type": "object",
        "description": "Error information if the node fails",
        "source": "=Error",
        "var": "error",
        "schema": {
          "$schema": "http://json-schema.org/draft-07/schema#",
          "type": "object",
          "required": [
            "code",
            "message",
            "detail",
            "category",
            "status"
          ],
          "properties": {
            "code": {
              "type": "string",
              "description": "Error code as a string"
            },
            "message": {
              "type": "string",
              "description": "High-level error message"
            },
            "detail": {
              "type": "string",
              "description": "Detailed error description"
            },
            "category": {
              "type": "string",
              "description": "Error category"
            },
            "status": {
              "type": "integer",
              "description": "HTTP status code"
            }
          },
          "additionalProperties": false
        }
      }
    },
    "form": {
      "id": "loop-properties",
      "title": "Loop configuration",
      "sections": [
        {
          "id": "iteration",
          "title": "Iteration",
          "fields": [
            {
              "name": "inputs.collection",
              "type": "custom",
              "component": "code-editor",
              "label": "Collection",
              "description": "Array or collection to iterate over (e.g., $vars.scriptTask1.output)",
              "componentProps": {
                "singleLine": true,
                "mode": "expression",
                "toggleable": false,
                "placeholder": "e.g., $vars.scriptTask1.output",
                "showVariableButton": true,
                "language": "javascript",
                "expectedType": "array",
                "validationMode": "expression"
              }
            },
            {
              "name": "inputs.parallel",
              "type": "switch",
              "label": "Parallel",
              "description": "Execute all iterations at the same time."
            },
            {
              "name": "inputs.completionCondition",
              "type": "custom",
              "component": "code-editor",
              "label": "Break on condition",
              "description": "Exit the loop early when this condition becomes true after an iteration completes.",
              "componentProps": {
                "singleLine": true,
                "mode": "expression",
                "toggleable": false,
                "placeholder": "e.g., $vars.processedCount >= 5",
                "showVariableButton": true,
                "alwaysIncludeSelf": true,
                "returnType": "boolean",
                "validationMode": "expression",
                "language": "javascript"
              }
            },
            {
              "name": "inputs.breakEnabled",
              "type": "switch",
              "label": "Show break handle",
              "description": "Allow nodes inside the loop to exit the loop early through a break handle."
            }
          ]
        }
      ]
    }
  },
  {
    "nodeType": "core.control.end",
    "version": "1.0",
    "category": "control-flow",
    "description": "Mark the end of a workflow path",
    "tags": [
      "control-flow",
      "end",
      "finish",
      "complete"
    ],
    "sortOrder": 20,
    "display": {
      "label": "End",
      "icon": "circle-check",
      "shape": "circle"
    },
    "handleConfiguration": [
      {
        "position": "left",
        "handles": [
          {
            "id": "input",
            "type": "target",
            "handleType": "input"
          }
        ]
      }
    ],
    "model": {
      "type": "bpmn:EndEvent"
    },
    "runtimeConstraints": {
      "exclude": [
        "api-function"
      ]
    }
  },
  {
    "nodeType": "core.trigger.manual",

"nodes": [
  {
    "id": "loop1.currentItem",
    "type": "any",
    "description": "The current item being iterated in the loop",
    "binding": {
      "nodeId": "loop1",
      "outputId": "currentItem"
    }
  },
  {
    "id": "loop1.currentIteration",
    "type": "number",
    "description": "The current iteration number (1-based)",
    "binding": {
      "nodeId": "loop1",
      "outputId": "currentIteration"
    }
  },
  {
    "id": "loop1.collection",
    "type": "array",
    "description": "The collection being iterated over",
    "binding": {
      "nodeId": "loop1",
      "outputId": "collection"
    }
  },
  {
    "id": "loop1.output",
    "type": "array",
    "description": "Aggregated results from all loop iterations",
    "binding": {
      "nodeId": "loop1",
      "outputId": "output"
    }
  },
  {
    "id": "start.output",

